function bindDocument(){hydrateMedia();$$('[data-field-step]').forEach(b=>{b.disabled=!!record.signed;b.onclick=()=>{wizard(+b.dataset.fieldStep);if(b.dataset.fieldFocus){const el=$('[data-ag="'+b.dataset.fieldFocus+'"]');el?.focus();el?.scrollIntoView({block:'center'})}}});$$('[data-variable]').forEach(b=>{b.disabled=!!record.signed;b.onclick=()=>{wizard(0);const el=$('.setup-body [name="'+b.dataset.variable+'"]');el?.focus();el?.scrollIntoView({block:'center'})}});$$('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));$$('[data-jump]').forEach(b=>b.onclick=()=>$('#doc-'+b.dataset.jump)?.scrollIntoView({behavior:'smooth'}))}
function bindEditor(){$('[data-back]').onclick=async()=>{try{await leave();location.hash=''}catch(e){showError(e)}};$$('[data-panel]').forEach(b=>b.onclick=()=>{panel=b.dataset.panel;renderEditor()});$$('[data-layout]').forEach(b=>b.onclick=()=>{draft.layout=b.dataset.layout;change();renderEditor()});$$('[data-hide]').forEach(x=>x.onchange=()=>{draft.hidden=draft.hidden.filter(id=>id!==x.dataset.hide);if(!x.checked)draft.hidden.push(x.dataset.hide);change();documentView();bindDocument()});$$('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action).catch(showError));bindDocument()}
async function act(name){if(name==='client'){document.body.classList.toggle('client-view');return}if(name==='print'){await save();window.print();return}if(name==='duplicate')return create('blank',draft);if(name==='template')return saveTemplate();if(name==='archive'){await save();const r=await json('/'+record.id+'/archive',{revision,archived:record.status!=='Archived'});record=r.record;revision=r.revision;renderEditor();return}if(name==='review')return review();if(name==='download-signed')return download(record.signed.pdfHash);if(name==='project')return createProject();if(record?.signed)throw Error('This agreement is locked. Duplicate it to make changes.');if(name==='media')return mediaEditor();if(name==='setup')return wizard(0);if(name==='import')return importer();if(name==='organize')return organizeSections();if(name==='add-section')return library();if(name==='pricebook')return feeBookEditor();if(name==='history')return historyView()}
function edit(id){if(record.signed)return;if(id==='fees'||id==='options')return wizard(2);if(id==='scope')return wizard(1);if(id==='timing')return wizard(4);if(id==='terms')return legal();if(id==='signature')return review();modal('Edit '+(sectionNames[id]||id.slice(6)),`<form id="text-form">${id.startsWith('extra:')?field('Section title','title',id.slice(6)):''}<label class="field"><span>Section text</span><textarea name="body" rows="10">${esc(draft.custom[id]||(id==='intro'?draft.intro:''))}</textarea></label><div class="modal-actions"><button class="primary">Save section</button>${id.startsWith('extra:')?'<button type="button" id="remove-section">Remove section</button>':''}</div></form>`);$('#remove-section')?.addEventListener('click',()=>{draft.removedSections||=[];draft.removedSections.push({id,text:draft.custom[id]});delete draft.custom[id];change();$('#modal').close();documentView();bindDocument()});addTokenPicker($('#text-form textarea'));$('#text-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(id.startsWith('extra:')){delete draft.custom[id];id='extra:'+String(f.get('title')).trim()}draft.custom[id]=String(f.get('body'));change();$('#modal').close();documentView();bindDocument()}}
async function loadTemplate(){return template||(template=await fetch('proposal-template.json').then(r=>r.json()))}
async function library(){const t=await loadTemplate();modal('Build your document from sections.',`<p class="modal-intro">Use a section heading, add your own text, or start with Studio H source wording. Source wording may contain client-specific terms and unresolved fields; review before use.</p><div class="block-choice"><h3>Your own section</h3><button id="custom-section">+ Custom section</button></div>${t.sections.map(s=>`<div class="block-choice"><h3>${esc(s.title)}</h3><p>Reusable starting text · requires review</p><button data-source="${s.id}">Use source wording</button><button data-heading="${s.id}">Heading only</button></div>`).join('')}`);$('#custom-section').onclick=()=>edit('extra:New section');$$('[data-source],[data-heading]').forEach(b=>b.onclick=()=>{const s=t.sections.find(s=>s.id===(b.dataset.source||b.dataset.heading)),id='extra:'+s.title;draft.custom[id]=b.dataset.source?s.markdown.replace(/^> ?/gm,''):'';change();edit(id)})}
async function legal(){const t=await loadTemplate();modal('Terms, with your review.',`<p class="modal-intro">Template wording and AI extraction are not legal advice. Have qualified counsel review your terms for your business and jurisdiction.</p><div class="notice"><b>Source conflict: 14 versus 21 days</b>The historical wording contains different cancellation notice periods. Reconcile this and any other conflicts before marking the terms reviewed. Enter your chosen cancellation rule in setup, too.</div><div class="term-controls"><button id="use-terms">Load 24 Studio H source clauses</button><button id="choose-clauses">Choose source clauses →</button><button id="use-exclusions">Load source exclusions</button></div><label class="field"><span>Terms and conditions · included in the document</span><textarea id="legal-text" rows="14">${esc(draft.legalText)}</textarea></label><label class="field"><span>Excluded services</span><textarea id="exclusions" rows="6">${esc(draft.exclusions)}</textarea></label><label class="check-row"><input class="switch" role="switch" type="checkbox" id="legal-reviewed" ${draft.legalReviewed?'checked':''}><span>I have reviewed the full wording, resolved source conflicts and completed all fields.</span></label><div class="modal-actions"><button class="primary" id="legal-save">Save wording</button></div>`);$('#choose-clauses').onclick=()=>{draft.legalText=$('#legal-text').value;draft.exclusions=$('#exclusions').value;change();clausePicker(t)};addTokenPicker($('#legal-text'));$('#use-terms').onclick=()=>{$('#legal-text').value=t.sections.find(s=>s.id==='K').markdown.replace(/^> ?/gm,'');$('#legal-reviewed').checked=false};$('#use-exclusions').onclick=()=>$('#exclusions').value=t.sections.find(s=>s.id==='G').markdown.replace(/^> ?/gm,'');$('#legal-text').oninput=()=>$('#legal-reviewed').checked=false;$('#legal-save').onclick=()=>{draft.legalText=$('#legal-text').value;draft.exclusions=$('#exclusions').value;draft.legalReviewed=$('#legal-reviewed').checked;markReviewed();$('#modal').close();documentView();bindDocument()}}
