async function rateDefaults(){await save();let revisionDefaults=null,profession=draft.profession||'Not specified',rates=structuredClone(draft.agreement.rates);const r=await fetch('/financials/defaults',{headers:{Authorization:'Bearer '+token()}});if(r.ok){const x=await r.json();revisionDefaults=x.revision;profession=x.state?.profession||profession;if(x.state?.rates?.length)rates=x.state.rates}modal('Studio billing defaults',`<p class="modal-intro">Defaults apply to new proposals. Existing drafts keep their saved rates until you choose to copy these.</p><label class="field"><span>Primary profession</span><select id="studio-profession">${['Not specified','Landscape architecture firm','Landscape / garden designer','Architect','Landscape contractor','Interior designer','Realtor','Other'].map(p=>`<option ${p===profession?'selected':''}>${p}</option>`).join('')}</select></label><p class="source-note">Profession describes your studio. Existing scope and prices are preserved; profession-specific benchmark datasets are not connected yet.</p><label class="field"><span>Role or person | hourly client rate</span><textarea id="default-rates" rows="8">${esc(rates.map(x=>x.name+' | '+x.rate).join('\n'))}</textarea></label><div class="modal-actions"><button id="copy-rates">Copy into this draft</button><button class="primary" id="save-rates">Save studio defaults</button></div>`);const read=()=>{const result=$('#default-rates').value.split('\n').filter(x=>x.trim()).map(x=>{const [name,rate]=x.split('|');if(!name?.trim()||rate?.trim()===''||!Number.isFinite(+rate)||+rate<0)throw Error('Use one role and non-negative rate per line.');return {name:name.trim(),rate:+rate}});if(!result.length)throw Error('Enter at least one role.');return result};$('#copy-rates').onclick=()=>{try{draft.agreement.rates=read();draft.profession=$('#studio-profession').value;change();wizard(3)}catch(e){showError(e)}};$('#save-rates').onclick=async()=>{try{const r=await fetch('/financials/defaults',{method:'POST',headers:{Authorization:'Bearer '+token(),'Content-Type':'application/json'},body:JSON.stringify({state:{rates:read(),profession:$('#studio-profession').value},revision:revisionDefaults})}),x=await r.json();if(!r.ok)throw Error(x.error);revisionDefaults=x.revision;toast('Studio billing defaults saved.')}catch(e){showError(e)}}}
function pricebook(){const b=bandFor(draft.budget);modal('Your rate sheet, beside your draft.',`<p class="modal-intro">2024 Studio H rate sheet · ${bandLabel()}. List prices are suggestions. Applying one does not change a phase fee automatically.</p><table class="rate-table"><thead><tr><th>Deliverable</th><th>List fee</th><th>Draft fee</th><th></th></tr></thead><tbody>${draft.agreement.items.map((i,n)=>`<tr><td>${esc(i.name)}${i.optional?'<small> · optional</small>':''}</td><td>${money(feeFor(i.id,draft.budget))}</td><td>${money(i.fee)}</td><td><button data-price="${n}" ${feeFor(i.id,draft.budget)===null?'disabled':''}>Use list</button></td></tr>`).join('')}</tbody></table><div class="notice"><b>Package pricing needs a scope check.</b>A full construction-document set already contains several services. Avoid adding duplicate plan fees. Phase fees remain authoritative when pricing by phase.</div><div class="modal-actions"><button id="sum-phases">Allocate selected core fees to phases</button><button class="primary" id="return-scope">Review scope →</button></div>`,true);$$('[data-price]').forEach(b=>b.onclick=()=>{const i=draft.agreement.items[+b.dataset.price];i.fee=feeFor(i.id,draft.budget);i.on=true;change();pricebook();documentView();bindDocument()});$('#sum-phases').onclick=()=>{for(let i=0;i<draft.agreement.phases.length;i++){const p=draft.agreement.phases[i],items=draft.agreement.items.filter(x=>x.on&&!x.optional&&x.phase===i);if(p.method==='Fixed fee'&&items.length&&items.every(x=>known(x.fee)))p.fee=items.reduce((s,x)=>s+x.fee,0)}change();documentView();bindDocument();toast('Selected core deliverable fees allocated. Review for duplicated scope.');};$('#return-scope').onclick=()=>wizard(2)}
function historyView(){const b=bandFor(draft.budget),m=median[b],fee=total(draft),list=catalogue.fullService[b],max=Math.max(m||0,fee||0,list||0,1)*1.15,point=(n,y,color)=>known(n)?`<circle cx="${60+n/max*480}" cy="${y}" r="8" fill="${color}"><title>${money(n)}</title></circle><text x="${60+n/max*480}" y="${y-15}" text-anchor="middle" fill="#293a32" font-size="15">${money(n)}</text>`:'';modal('How this fee compares.',`<p class="modal-intro">${bandLabel()} · ${counts[b]||0} proposals in the published history summary. Scope varies; this is pricing context, not profitability data.</p><div class="history-chart"><svg viewBox="0 0 620 210" role="img" aria-label="Draft fee, historical median and published package price"><path d="M60 70H560M60 125H560M60 180H560" stroke="#dce6d5" stroke-width="2"/><text x="4" y="74" font-size="10">Draft</text><text x="4" y="129" font-size="10">Median</text><text x="4" y="184" font-size="10">Website</text>${point(fee,70,'#527444')}${point(m,125,'#7498a7')}${point(list,180,'#ce0087')}</svg></div><p>${m&&known(fee)?`${Math.abs((fee/m-1)*100).toFixed(1)}% ${fee>=m?'above':'below'} the historical median.`:'No comparable history available.'}</p><label class="field"><span>Pricing review note</span><textarea id="pricing-note" rows="3">${esc(draft.pricingReason)}</textarea></label><p class="source-note">More than 25% from the median prompts review. This is a studio review setting, not a statistical conclusion. Source: PROPOSAL-BUILDER.md Appendix 2; 55 proposals reviewed, 39 represented in band summaries. Website package pricing and rate-sheet line items can differ.</p><div class="modal-actions"><button class="primary" id="pricing-save">Save review note</button></div>`);$('#pricing-save').onclick=()=>{draft.pricingReason=$('#pricing-note').value;change();$('#modal').close()}}
async function importer(){if(record.signed)return;await save();modal('Turn a proposal into reusable sections.',`<p class="modal-intro">Upload a PDF or Word document. AI reads the scope and wording; you review the extracted evidence before applying it.</p><label class="upload-area"><b>Choose your proposal</b><p>PDF or DOCX · up to 20 MB · PDF AI reading up to 10 MB</p><input id="proposal-file" type="file" accept=".pdf,.docx"><p id="upload-note" class="source-note">Stored privately with this proposal.</p></label><div id="import-actions"></div>`);$('#proposal-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const note=$('#upload-note');try{note.textContent='Uploading securely…';const f=await upload(file);draft.sourceDocument={id:f.id,name:file.name};change();await save();note.textContent=file.name+' · stored privately';$('#import-actions').innerHTML='<div class="modal-actions"><button id="read-ai" class="primary">Read with AI →</button></div>';$('#read-ai').onclick=async()=>{const button=$('#read-ai');button.disabled=true;note.textContent='Reading sections and source references…';try{const data=await json('/'+record.id+'/extract',{documentId:f.id,...(file.name.toLowerCase().endsWith('.docx')?{text:await docxText(file)}:{})});importReview(data)}catch(e){note.textContent=e.message;button.disabled=false}}}catch(e){note.textContent=e.message}}}
async function upload(file){if(file.size>20*1024*1024)throw Error('Choose a file smaller than 20 MB.');const bytes=await file.arrayBuffer(),id=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join(''),mime=/\.pdf$/i.test(file.name)?'application/pdf':/\.docx$/i.test(file.name)?'application/vnd.openxmlformats-officedocument.wordprocessingml.document':null;if(!mime)throw Error('Choose a PDF or DOCX file.');await api('/'+record.id+'/document/'+id,{method:'PUT',headers:{'Content-Type':mime},body:bytes});return {id}}
function importReview(result){const x=result.extracted;modal('Review what the document says.',`<p class="modal-intro">AI extraction is evidence to check, not an approved agreement. Unknown values remain blank. Applying creates a new draft, preserving this one.</p><div class="two-fields"><div class="source-block"><b>Construction estimate</b><p>${money(x.constructionEstimate)}</p></div><div class="source-block"><b>Construction cap</b><p>${money(x.constructionCap)}</p></div></div>${(x.notes||[]).map(n=>`<div class="notice">${esc(n)}</div>`).join('')}<h3>Extracted phases</h3>${x.phases.map(p=>`<div class="source-block"><b>${esc(p.name)}</b><p>${esc(p.method)} · ${money(p.fee)} · ${esc(p.source)}</p></div>`).join('')}<h3>Document sections</h3>${x.sections.map((s,i)=>`<div class="source-block"><label class="check-row"><input type="checkbox" class="switch" role="switch" data-import-section="${i}" checked><b>${esc(s.title)}</b></label><small>${esc(s.source)}</small><textarea rows="5" data-import-text="${i}">${esc(s.text)}</textarea></div>`).join('')}<div class="notice">Before saving a reusable template, remove client names, addresses, dates and client-specific fees from the wording. The app cannot guarantee AI has removed every identifier.</div><div class="modal-actions"><button class="primary" id="apply-import">Create draft from reviewed extraction</button></div>`,true);$('#apply-import').onclick=async()=>{try{const d=blank();d.name=record.draft.name+' · imported';d.client=String(x.client||'');d.address=String(x.address||'');d.budget=known(x.constructionEstimate)?x.constructionEstimate:'';d.cap=known(x.constructionCap)?x.constructionCap:'';d.agreement.budget=d.budget;d.agreement.phases=x.phases.map(p=>({...phase(String(p.name||'Phase'),['Hourly','Included'].includes(p.method)?p.method:'Fixed fee'),fee:known(p.fee)?p.fee:'',duration:known(p.duration)?p.duration:'',unit:['days','weeks','months'].includes(p.unit)?p.unit:'weeks'}));d.agreement.items=(x.deliverables||[]).map(i=>({...item(String(i.name||'Deliverable'),crypto.randomUUID()),on:true,phase:d.agreement.phases.findIndex(p=>p.name===i.phaseName),fee:known(i.fee)?i.fee:'',optional:!!i.optional}));if(Array.isArray(x.rates)&&x.rates.length)d.agreement.rates=x.rates.filter(r=>known(r.rate)).map(r=>({name:String(r.name),rate:r.rate}));$$('[data-import-section]:checked').forEach(el=>{const i=+el.dataset.importSection,s=x.sections[i],body=$(`[data-import-text="${i}"]`).value;if(/terms|conditions|legal/i.test(s.title))d.legalText+=(d.legalText?'\n\n':'')+body;else if(/excluded|exclusion/i.test(s.title))d.exclusions+=body+'\n';else d.custom['extra:'+s.title]=body});d.importEvidence={sourceDocumentId:result.documentId,extractedAt:result.at,notes:x.notes||[],sources:x.sections.map(s=>({title:s.title,source:s.source}))};validate(d);await create('blank',d);$('#modal').close();toast('New draft created. Review pricing, billing and all source wording.')}catch(e){showError(e)}}}
async function saveTemplate(){modal('Save a reusable template',`<p class="modal-intro">A template retains layout, sections, scope and billing defaults. Client fields are cleared. Check section text for names, dates and client-specific terms before reusing it.</p><label class="check-row"><input id="template-confirm" class="switch" type="checkbox" role="switch"><span>I reviewed the text for client-specific information.</span></label><div class="modal-actions"><button id="template-save" class="primary" disabled>Save separate template</button></div>`);$('#template-confirm').onchange=e=>$('#template-save').disabled=!e.target.checked;$('#template-save').onclick=async()=>{try{await create('blank',draft,'template');$('#modal').close()}catch(e){showError(e)}}}
function review(){if(record.signed){modal('Executed agreement retained',`<p class="modal-intro">${esc(record.signed.method)} · ${esc(record.signed.signedDate)}</p><p>Client: ${esc(record.signed.clientSigner)}<br>Studio: ${esc(record.signed.studioSigner)}</p><p class="source-note">PDF checksum: ${record.signed.pdfHash}</p><div class="modal-actions"><button id="signed-download">Download executed PDF</button><button id="signed-project" class="primary">${record.projectId?'Open project':'Create project'}</button></div>`);$('#signed-download').onclick=()=>download(record.signed.pdfHash).catch(showError);$('#signed-project').onclick=()=>createProject().catch(showError);return}const c=checks(draft);modal('Before this proposal goes out.',`<p class="modal-intro">Required fields follow the selected agreement. A construction cap is required only when its provision is enabled.</p>${c.map(x=>`<div class="check-row ${x.ok?'':'bad'}"><i>${x.ok?'✓':'!'}</i><span><b>${x.title}</b></span></div>`).join('')}<div class="notice"><b>Electronic signing is not enabled yet.</b>You can finish and save the proposal now. Native Studio H signing or an embedded provider will add verified signer access, document locking, evidence and client downloads. No invitation is sent by this screen.</div><div class="modal-actions"><button id="review-inputs">Review setup</button><button id="record-executed" ${c.every(x=>x.ok)?'':'disabled'}>Record an already-signed PDF</button><button class="primary" disabled>Send for signature</button></div>`);$('#review-inputs').onclick=()=>wizard(0);$('#record-executed').onclick=recordSigned}
async function recordSigned(){await save();modal('Record an already-signed agreement',`<p class="modal-intro">This records a PDF that was signed outside Studio H. It does not generate a signature or certify authenticity. Confirm the PDF matches this proposal’s scope and billing fields before locking the record.</p><form id="signed-form"><div class="two-fields">${field('Client signer','clientSigner',draft.client,'text','required')}${field('Studio signer','studioSigner','','text','required')}${field('Signed date','signedDate','','date','required')}</div><label class="field"><span>Executed PDF</span><input type="file" name="file" accept=".pdf" required></label><label class="check-row"><input class="switch" role="switch" type="checkbox" name="confirmed" required><span>I checked both signatures and confirmed that these structured fields match the executed agreement.</span></label><div class="modal-actions"><button class="primary">Retain signed PDF & lock proposal</button></div></form>`);$('#signed-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.submitter;b.disabled=true;try{const doc=await upload(f.get('file')),r=await json('/'+record.id+'/signed',{revision,documentId:doc.id,clientSigner:f.get('clientSigner'),studioSigner:f.get('studioSigner'),signedDate:f.get('signedDate'),confirmed:f.get('confirmed')==='on'});record=r.record;revision=r.revision;$('#modal').close();renderEditor();status('Signed PDF retained')}catch(e){b.disabled=false;showError(e)}}}
async function download(id){const r=await api('/'+record.id+'/document/'+id),url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='Studio-H-executed-proposal.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function createProject(){await save();if(record.projectId){location.href='../../?proposalProject='+encodeURIComponent(record.projectId);return}modal('Start the project from this agreement.',`<p class="modal-intro">The new project receives client and property details, accepted scope, phases, fee and billing rules. The executed proposal stays here, unchanged.</p><div class="total-row"><span>${esc(draft.name)}</span><strong>${money(record.signed.document.fee)}</strong></div><div class="modal-actions"><button class="primary" id="convert-project">Create project</button></div>`);$('#convert-project').onclick=async e=>{e.target.disabled=true;try{const r=await json('/'+record.id+'/project',{revision});record=r.record;revision=r.revision;$('#modal').close();renderEditor();toast('Project created. The signed agreement is preserved.')}catch(err){e.target.disabled=false;showError(err)}}}
async function route(){const m=location.hash.match(/^#proposal\/([\w-]+)$/);try{if(m){if(record?.id===m[1])return;await open(m[1])}else await hub()}catch(e){showError(e);if(!record)$('#app').innerHTML=`<div class="empty"><h2>Open your studio first.</h2><p>${esc(e.message)}</p><a href="../../?workspace=proposals">Return to Studio H sign-in →</a></div>`}}
window.addEventListener('hashchange',route);

async function docxText(file){const bytes=new Uint8Array(await file.arrayBuffer()),v=new DataView(bytes.buffer);let end=bytes.length-22;for(;end>=Math.max(0,bytes.length-65557);end--)if(v.getUint32(end,true)===0x06054b50)break;if(end<0)throw Error('The DOCX archive is not readable. Export it as PDF.');let pos=v.getUint32(end+16,true),count=v.getUint16(end+10,true);for(let i=0;i<count;i++){if(v.getUint32(pos,true)!==0x02014b50)break;const method=v.getUint16(pos+10,true),compressed=v.getUint32(pos+20,true),size=v.getUint32(pos+24,true),len=v.getUint16(pos+28,true),extra=v.getUint16(pos+30,true),comment=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.subarray(pos+46,pos+46+len));if(name==='word/document.xml'){if(size>2000000)throw Error('Please use a shorter proposal or PDF export.');const start=offset+30+v.getUint16(offset+26,true)+v.getUint16(offset+28,true),chunk=bytes.subarray(start,start+compressed);let stream=new Blob([chunk]).stream();if(method===8)stream=stream.pipeThrough(new DecompressionStream('deflate-raw'));else if(method!==0)throw Error('Unsupported Word compression. Export as PDF.');const reader=stream.getReader();let chunks=[],total=0;while(true){const {value,done}=await reader.read();if(done)break;total+=value.length;if(total>2000000){await reader.cancel();throw Error('Word document is too large.')}chunks.push(value)}let xml=await new Blob(chunks).text(),dom=new DOMParser().parseFromString(xml,'application/xml');const extracted=[...dom.getElementsByTagName('w:p')].map((p,i)=>'Paragraph '+(i+1)+': '+p.textContent).join('\n');if(extracted.length>180000)throw Error('This Word document exceeds the extraction limit. Split it into sections; no partial text was sent.');return extracted}pos+=46+len+extra+comment}throw Error('No Word document text was found. Export as PDF.')}
function mileageLookup(){modal('Verified mileage references',`<p class="modal-intro">Federal business mileage reference. Your agreement determines what clients pay. State-specific reimbursement requirements are separate.</p><p><a href="${mileageSource}" target="_blank" rel="noopener">IRS source and effective periods ↗</a> · checked October 4, 2026</p>${mileageReferences.map((r,i)=>`<div class="check-row"><span>${r.start} – ${r.end}</span><b>$${r.rate.toFixed(3)} / mile</b><button data-mile="${i}">Use this reference</button></div>`).join('')}<p class="source-note">No future-year rate is assumed. This is a sourced reference table, not an AI-generated rate.</p>`);$$('[data-mile]').forEach(b=>b.onclick=()=>{const r=mileageReferences[+b.dataset.mile];draft.agreement.mileRate=r.rate;draft.agreement.mileSource=`IRS ${r.start} to ${r.end} · ${mileageSource}`;change();wizard(3)})}
function nextBandReview(){const result=nextBand(draft);modal('Review the next budget band',result.error?`<p>${esc(result.error)}</p><button id="band-return">Return to changes</button>`:`<p class="modal-intro">Selected core services at next-band prices from the proposal’s fee book, including eligible package discounts. Optional and hourly work are excluded. Review the scope before proposing a change.</p><div class="total-row"><span>Current fee</span><b>${money(total(draft))}</b></div><div class="total-row"><span>Next-band list fee · through ${money(result.cap)}</span><b>${money(result.fee)}</b></div><div class="total-row"><span>Proposed difference</span><strong>${known(total(draft))?money(result.fee-total(draft)):'Set current fee'}</strong></div>${result.rows.map(r=>`<div class="mini-line"><span>${esc(r.name)}</span><b>${money(r.fee)}</b></div>`).join('')}<button class="primary" id="band-use">Use as proposed revised fee</button><p>No signed fee changes until approved.</p>`);$('#band-return')?.addEventListener('click',()=>wizard(5));$('#band-use')?.addEventListener('click',()=>{draft.agreement.newFee=result.fee;draft.agreement.nextBandEvidence=result;change();wizard(5)})}
async function attachAddress(sync){const el=$('.setup-body [name="address"]');if(!el)return;const box=$('#address-results');box.innerHTML='<small>Address suggestions loading… Manual entry remains available.</small>';try{await loadPlaces();if(!el.isConnected)return;const svc=new google.maps.places.AutocompleteService(),details=new google.maps.places.PlacesService(document.createElement('div'));let timer,serial=0;el.addEventListener('input',()=>{clearTimeout(timer);const ticket=++serial;if(el.value.length<3){box.innerHTML='';return}timer=setTimeout(()=>svc.getPlacePredictions({input:el.value,types:['address'],componentRestrictions:{country:(draft.property.country||'US').toLowerCase()}},(items,status)=>{if(ticket!==serial||!el.isConnected)return;box.innerHTML=status==='OK'?items.map((p,i)=>`<button type="button" data-place="${i}">${esc(p.description)}</button>`).join('')+'<small>Powered by Google</small>':'<small>No suggestions available. Enter the address fields manually.</small>';box.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>details.getDetails({placeId:items[+b.dataset.place].place_id,fields:['formatted_address','address_components']},(p,status)=>{if(status!=='OK'||!el.isConnected)return;const c=type=>p.address_components.find(c=>c.types.includes(type)),long=t=>c(t)?.long_name||'',short=t=>c(t)?.short_name||'';const values={address:p.formatted_address,street:[long('street_number'),long('route')].filter(Boolean).join(' '),unit:long('subpremise'),city:long('locality')||long('postal_town')||long('sublocality'),state:short('administrative_area_level_1'),postalCode:long('postal_code'),country:short('country')};for(const[k,v]of Object.entries(values)){const input=$('.setup-body [name="'+k+'"]');if(input)input.value=v}box.innerHTML='';sync()}))}),250)});box.innerHTML='<small>Start typing to search. You can correct every field.</small>'}catch{box.innerHTML='<small>Address suggestions unavailable. Please enter the address fields manually.</small>'}}
let placesPromise;function loadPlaces(){if(window.google?.maps?.places)return Promise.resolve();return placesPromise??=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./places-config.js';s.onload=()=>{if(!window.studioPlacesUrl){reject();return}const g=document.createElement('script');g.src=window.studioPlacesUrl;g.onload=()=>window.google?.maps?.places?resolve():reject();g.onerror=reject;document.head.append(g)};s.onerror=reject;document.head.append(s);setTimeout(()=>reject(Error('Address lookup timeout')),12000)}).catch(e=>{placesPromise=null;throw e})}
const variableLabels={'client.name':'Client display name','client.firstName':'Client first name','client.lastName':'Client last name','client.company':'Client company','client.email':'Client email','property.address':'Property full address','property.street':'Street address','property.unit':'Unit','property.city':'City','property.state':'State','property.postalCode':'ZIP / postal code','property.country':'Country','proposal.name':'Proposal title','construction.cap':'Construction cap','construction.estimate':'Construction estimate'};
function addTokenPicker(textarea){if(!textarea)return;const area=document.createElement('details');area.innerHTML='<summary>Insert a linked variable</summary><input aria-label="Search variables" placeholder="Find a variable…"><div class="token-list"></div>';textarea.parentElement.after(area);const draw=q=>{area.querySelector('.token-list').innerHTML=Object.entries(variableLabels).filter(([k,v])=>(k+' '+v).toLowerCase().includes(q.toLowerCase())).map(([k,v])=>`<button type="button" data-token="${k}">${esc(v)}</button>`).join('');area.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{const start=textarea.selectionStart,end=textarea.selectionEnd,value='{{'+b.dataset.token+'}}';textarea.setRangeText(value,start,end,'end');textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.focus()})};area.querySelector('input').oninput=e=>draw(e.target.value);draw('')}
function fieldsInspector(){const values=variables(draft);$('#inspector').innerHTML='<input id="field-search" placeholder="Find a field…" aria-label="Find a field">'+Object.entries(variableLabels).map(([key,label])=>`<label class="field" data-field-label="${label.toLowerCase()}"><span>${label}</span><input data-token-field="${key}" value="${esc(key.startsWith('construction.')&&values[key]!==''?money(values[key]):values[key]??'')}" ${key.startsWith('construction.')?'data-money inputmode="decimal"':''} ${record.signed?'disabled':''}></label>`).join('')+'<button data-open-address>Find property address →</button>';$('#field-search').oninput=e=>$$('[data-field-label]').forEach(x=>x.hidden=!x.dataset.fieldLabel.includes(e.target.value.toLowerCase()));$$('[data-token-field]').forEach(el=>el.onchange=()=>{const [group,key]=el.dataset.tokenField.split('.');if(group==='property'&&key!=='address'){draft.property||={};draft.property[key]=el.value}else if(group==='client'&&!['name','email'].includes(key)){draft.contact||={};draft.contact[key]=el.value}else if(group==='construction'){const amount=window.agMoneyValue(el);if(amount!==''&&(!Number.isFinite(amount)||amount<0)){el.setCustomValidity('Enter a non-negative number.');el.reportValidity();return}el.setCustomValidity('');draft[key==='estimate'?'budget':'cap']=amount;draft.agreement.budget=draft.budget;syncBookItems(draft.agreement,draft.budget)}else draft[({'client.name':'client','client.email':'email','property.address':'address','proposal.name':'name'})[el.dataset.tokenField]]=el.value;change();documentView();bindDocument()});$('[data-open-address]').onclick=()=>wizard(0)}
function templateThumbnail(k){return `<div class="template-mini ${k}"><small>STUDIO H · DESIGN PROPOSAL</small><h3>${k==='c'?'Let’s make room for living.':'Your next landscape.'}</h3>${k==='b'?'':'<div class="mini-image"></div>'}<div class="mini-fee">Your design fee</div>${Array.from({length:k==='b'?6:2},()=>'<div class="mini-line"></div>').join('')}</div>`}
async function proposalPicker(){modal('Choose your proposal layout',`<p class="modal-intro">These are three visual layouts for the same scope, pricing and terms. Switch layouts later without re-entering your information.</p><div class="template-examples">${Object.entries(layouts).map(([k,v])=>`<div class="template-example">${templateThumbnail(k)}<h3>${k.toUpperCase()} · ${v}</h3><p>${k==='a'?'Photography-led cover, fee panel and phase cards. Studio default.':k==='b'?'Compact cover, clear pricing tables and a shorter introduction.':'Large visual opening and chapter navigation for a guided presentation.'}</p><button data-example="${k}">See example ↗</button><button class="primary" data-start-layout="${k}">Use this layout</button></div>`).join('')}</div>`,true);$$('[data-example]').forEach(b=>b.onclick=()=>templateExample(b.dataset.example));$$('[data-start-layout]').forEach(b=>b.onclick=()=>startLayout(b.dataset.startLayout))}
async function startLayout(layout){try{await create('blank');draft.layout=layout;change();renderEditor();wizard(0)}catch(e){showError(e)}}
function templateExample(layout){const previous={draft,record},sample=example();draft=sample;draft.layout=layout;record={id:'EXAMPLE1',created:new Date().toISOString(),signed:null};const html=cover();draft=previous.draft;record=previous.record;modal(layouts[layout]+' · visual example',`<p class="source-note">Fictional sample, shown only to preview the layout. Your new proposal starts empty.</p><article class="doc ${layout==='b'?'compact':layout==='c'?'guided':''}">${html}<div class="doc-section"><h3>The work we will do</h3><p>Scope, fees, timing and your selected terms follow this cover.</p></div></article><div class="modal-actions"><button id="example-back">← All layouts</button><button id="example-use" class="primary">Use this layout</button></div>`,true);$$('#modal .variable-edit').forEach(b=>b.disabled=true);$('#example-back').onclick=proposalPicker;$('#example-use').onclick=()=>startLayout(layout)}

const mediaCache=new Map();let slideTimer;async function mediaBlob(id,proposalId=record.id){const key=proposalId+'/'+id;if(!mediaCache.has(key)){const r=await api('/'+proposalId+'/media/'+id);mediaCache.set(key,URL.createObjectURL(await r.blob()))}return mediaCache.get(key)}
async function mediaEditor(){if(record.signed)return;draft.media||={mode:'single',items:[]};const m=draft.media;modal('Design & media',`<p class="modal-intro">Your cover can be a photograph, a slideshow or video. The first photograph is also the PDF cover. Files stay private within your studio.</p><label class="field"><span>Cover format</span><select id="media-mode">${[['single','Single photograph'],['slideshow','Photo slideshow'],['video','Video with photo for PDF']].map(([k,v])=>`<option value="${k}" ${m.mode===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="upload-area">Add JPG, PNG, WebP, MP4 or WebM · maximum 20 MB each<input id="media-file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><p id="media-status"></p>${m.items.map((i,n)=>`<div class="source-block"><b>${i.type.startsWith('video')?'Video':'Photograph'} ${n+1}</b><label class="field"><span>Caption / image description</span><input data-media-caption="${n}" value="${esc(i.caption||'')}"></label><button data-media-up="${n}" ${n===0?'disabled':''}>Move up ↑</button><button data-media-remove="${n}">Remove from proposal</button></div>`).join('')}<p class="source-note">The slideshow has pause controls. Video plays muted where supported, with playback controls. Keep a photograph first for print/PDF. No client-view tracking is enabled yet.</p><button id="media-done" class="primary">Save & return to proposal</button>`);$('#media-mode').onchange=e=>{m.mode=e.target.value;change()};$$('[data-media-caption]').forEach(el=>el.onchange=()=>{m.items[+el.dataset.mediaCaption].caption=el.value;change()});$$('[data-media-up]').forEach(b=>b.onclick=()=>{const n=+b.dataset.mediaUp;[m.items[n-1],m.items[n]]=[m.items[n],m.items[n-1]];change();mediaEditor()});$$('[data-media-remove]').forEach(b=>b.onclick=()=>{m.items.splice(+b.dataset.mediaRemove,1);change();mediaEditor()});$('#media-file').onchange=async e=>{const files=[...e.target.files];if(m.items.length+files.length>12){$('#media-status').textContent='Use up to 12 cover files.';return}e.target.disabled=true;try{await save();for(const file of files){if(file.size>20*1024*1024)throw Error('Each file must be under 20 MB.');const bytes=await file.arrayBuffer(),id=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');await api('/'+record.id+'/media/'+id,{method:'PUT',headers:{'Content-Type':file.type},body:bytes});m.items.push({id,type:file.type,caption:''});change();}await save();mediaEditor()}catch(err){$('#media-status').textContent=err.message;e.target.disabled=false}};$('#media-done').onclick=async()=>{try{await save();$('#modal').close();documentView();bindDocument()}catch(e){showError(e)}}}
async function hydrateMedia(){clearInterval(slideTimer);const target=$('.garden'),m=draft.media,pid=record.id;if(!target||!m?.items?.length)return;const photos=m.items.filter(i=>i.type.startsWith('image')),video=m.items.find(i=>i.type.startsWith('video'));target.style.position='relative';try{const photo=photos[0],url=photo?await mediaBlob(photo.id,pid):null;if(!target.isConnected)return;if(url){target.style.backgroundImage='none';target.innerHTML=`<img class="proposal-cover-photo" src="${url}" alt="${esc(photo.caption||'Project photograph')}">`}else target.innerHTML='<span class="photo-label">Add a photograph for the PDF cover</span>';if(m.mode==='video'&&video){const v=document.createElement('video');v.className='media-video';v.controls=true;v.muted=true;v.autoplay=true;v.playsInline=true;if(url)v.poster=url;v.src=await mediaBlob(video.id,pid);if(target.isConnected)target.append(v)}if(m.mode==='slideshow'&&photos.length>1){let index=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;const control=document.createElement('button');control.className='slideshow-control';control.textContent=paused?'Play slideshow':'Pause slideshow';control.onclick=()=>{paused=!paused;control.textContent=paused?'Play slideshow':'Pause slideshow'};target.append(control);slideTimer=setInterval(async()=>{if(paused||document.hidden||!target.isConnected)return;index=(index+1)%photos.length;const item=photos[index],u=await mediaBlob(item.id,pid),img=target.querySelector('img');if(img){img.src=u;img.alt=item.caption||'Project photograph'}},5000)}}catch{if(target.isConnected)target.innerHTML='<span class="photo-label">Media unavailable. Open Design & media to review.</span>'}}
function clausePicker(t){const source=t.sections.find(s=>s.id==='K').markdown.replace(/^> ?/gm,''),start=source.search(/^1\. /m),intro=source.slice(0,start),clauses=source.slice(start).split(/\n(?=\d+\. )/);modal('Choose Studio H source clauses',`<p class="modal-intro">These are your historical source clauses, not universally applicable legal templates. Select the wording to insert, then edit and review it. Conflicting notice periods and billing terms still need reconciliation.</p>${clauses.map((c,i)=>`<details class="source-block"><summary><label class="check-row"><input class="switch" role="switch" type="checkbox" data-clause="${i}" ${draft.legalText.includes(c)?'checked':''}>Clause ${i+1} · ${esc(c.replace(/^\d+\. /,'').slice(0,80))}…</label></summary><p class="doc-text">${esc(c)}</p></details>`).join('')}<button id="apply-clauses" class="primary">Append selected wording for review</button>`,true);$('#apply-clauses').onclick=()=>{const selected=$$('[data-clause]:checked').map(x=>clauses[+x.dataset.clause]).filter(c=>!draft.legalText.includes(c));if(selected.length){draft.legalText+=(draft.legalText?'\n\n':intro)+selected.join('\n\n');draft.legalEvidence={source:'Studio H source proposals · proposal-template.json',selectedAt:new Date().toISOString()};change()}legal()}}
function organizeSections(){const entries=Object.entries(draft.custom).filter(([k])=>k.startsWith('extra:'));modal('Organize additional text sections',`<p class="modal-intro">Additional sections appear before acceptance. Move them into the order you want. Removed sections can be restored.</p>${entries.map(([k,v],i)=>`<div class="check-row"><b>${esc(k.slice(6))}</b><button data-section-up="${i}" ${i?'':'disabled'}>Move up ↑</button><button data-section-edit="${i}">Edit</button></div>`).join('')||'<p>No additional text sections yet. Use Add a section.</p>'}${(draft.removedSections||[]).map((r,i)=>`<div class="check-row"><span>${esc(r.id.slice(6))}</span><button data-restore-section="${i}">Restore</button></div>`).join('')}`);$$('[data-section-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.sectionUp;[entries[i-1],entries[i]]=[entries[i],entries[i-1]];draft.custom=Object.fromEntries([...Object.entries(draft.custom).filter(([k])=>!k.startsWith('extra:')),...entries]);change();documentView();bindDocument();organizeSections()});$$('[data-section-edit]').forEach(b=>b.onclick=()=>edit(entries[+b.dataset.sectionEdit][0]));$$('[data-restore-section]').forEach(b=>b.onclick=()=>{const i=+b.dataset.restoreSection,r=draft.removedSections[i];let key=r.id;while(key in draft.custom)key+=' · restored';draft.custom[key]=r.text;draft.removedSections.splice(i,1);change();documentView();bindDocument();organizeSections()})}
window.addEventListener('beforeprint',()=>{clearInterval(slideTimer);const photo=draft?.media?.items?.find(i=>i.type.startsWith('image')),img=$('.proposal-cover-photo'),url=photo&&mediaCache.get(record.id+'/'+photo.id);if(img&&url){img.src=url;img.alt=photo.caption||'Project photograph'}});
window.addEventListener('afterprint',()=>{if(draft)hydrateMedia()});

function pricingQuestion(){const methods=['Fixed design fee','Fee by construction budget band','Percentage of construction budget','Hourly','Combination / custom'];return `<section class="source-block"><h3>How do you price this proposal?</h3><p>Choose the fee method first. Billing dates and payment terms come later.</p><div class="pricing-options">${methods.map(m=>`<button data-pricing-method="${esc(m)}" class="${draft.agreement.feeMethod===m?'active':''}">${esc(m)}</button>`).join('')}</div><button id="early-fee-book">Set up your studio fee book →</button></section>`}
function bindPricingQuestion(v,step){$$('[data-pricing-method]').forEach(b=>b.onclick=()=>{pricingMethod(draft.agreement,b.dataset.pricingMethod);change();documentView();bindDocument();wizard(0)});$('#early-fee-book')?.addEventListener('click',()=>feeBookEditor());}
function feeBookEditor(){return openFeeBook({modal,token,current:draft.agreement.feeBook,onError:showError,onApply:book=>{draft.agreement.feeBook=book;draft.agreement.autoPhaseFees=true;syncBookItems(draft.agreement,draft.agreement.budgetType==='Range'?draft.agreement.budgetMax:draft.budget,{replace:true});change();documentView();bindDocument();wizard(2);toast('Fee book applied to this draft. Review selected services and phase totals.')}}).catch(showError)}
function packageSummary(a){const ds=discounts(a);if(!a.autoPhaseFees&&a.basis!=='Fees by deliverable')return '';if(!ds.length||a.basis==='Percentage of construction budget'||a.pricing==='Hourly')return '';return `<div class="pricing-summary"><h4>Service prices & package savings</h4>${ds.map(p=>`<p><b>${esc(p.name)}</b> · ${p.percent}% discount</p>${p.ids.map(id=>{const i=a.items.find(i=>i.id===id);return `<div class="mini-line"><span>${esc(i.name)} · list price</span><b>${money(i.fee)}</b></div>`}).join('')}<div class="mini-line"><span>Package discount · included in total</span><b>−${money(p.amount)}</b></div>`).join('')}<small>Discount applies while all package services are included. Removing a service removes its package discount.</small></div>`}
try{const r=await fetch('/session',{headers:{Authorization:'Bearer '+token()}});if(!r.ok)throw Error('Sign in to Studio H to access private proposals.');session=await r.json();if(session.demo||session.role!=='admin')throw Error('Proposals are currently available to studio administrators.');await route()}catch(e){status('Sign-in required');$('#app').innerHTML=`<div class="empty"><h2>Your proposals stay private.</h2><p>${esc(e.message)}</p><a href="../../?workspace=proposals">Sign in to Studio H →</a></div>`}
